def level_order(nodes: list) -> list[list[int]]:
    if not nodes or nodes[0] is None:
        return []
    levels = []
    idx = 0
    sz = 1
    while idx < len(nodes):
        chunk = [x for x in nodes[idx:idx + sz] if x is not None]
        if chunk:
            levels.append(chunk)
        idx += sz
        sz *= 2
    return levels
